// r11-e3-cluster2-s: r6 (c1-control-r6) with a cluster-of-2 launch for small and large token counts.
// Per-head RMSNorm of Q and K (fp32), one fused one-shot launch. 16 rows per 256-thread CTA, half-warp per row,
// 256-bit ld/st on sm_100a, output stores L2 evict_last. B*S <= 600: x loads L2 evict_first, weights ld.global.nc.
// Launch attribute under test (experiment E3 / H14): __cluster_dims__(2,1,1) cut the CUPTI time of the 12.6-25 MB
// workloads by about 3% on the rented B200 (empty kernels showed no change). Used for B*S <= 300 and B*S >= 2048;
// 586..1024 tokens run the plain launch (cluster 2 measured +0.6..+1.6% there).
#include <cuda_runtime.h>
#include <cstdint>

namespace {
constexpr int D = 128;
constexpr int H = 48;
constexpr int ROWS = 16;
constexpr int THREADS = 256;
constexpr int GROUPS = H / ROWS;
constexpr uint64_t POL_EVICT_FIRST = 0x12F0000000000000ULL;   // CUTLASS CacheHintSm90::EVICT_FIRST

__device__ __forceinline__ uint64_t pol_evict_last() {
    uint64_t p;
    asm volatile("createpolicy.fractional.L2::evict_last.b64 %0, 1.0;" : "=l"(p));
    return p;
}

#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 1000)
__device__ __forceinline__ void ld8(const float* p, float (&v)[8]) {
    asm volatile("ld.global.v8.f32 {%0,%1,%2,%3,%4,%5,%6,%7}, [%8];"
                 : "=f"(v[0]), "=f"(v[1]), "=f"(v[2]), "=f"(v[3]),
